window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8f012ddb9fff5ed4"]={"versions": [{"id": "FIG-8f012ddb9fff5ed4", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des E2E-Profils 4 (E2E Profile 4) innerhalb der AUTOSAR-E2E-Bibliothek (E2E Protocol). Das Diagramm definiert den Teilschritt „Increment Counter“ innerhalb der Schutzfunktion <code>E2E_P04Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktionskontext: <code>E2E_P04Protect()</code> (dargestellt als abgerundetes Rechteck mit Rake-/Subaktivitätssymbol).</li>\n<li>Startknoten (Initial Node): Ausgefüllter schwarzer Kreis.</li>\n<li>Aktion / Aktivitätszustand: <code>State-&gt;Counter++</code> (Inkrementierung des Zähler-Attributs in der Zustandsstruktur <code>State</code>).</li>\n<li>Notizsymbol (Comment/Note), assoziiert über eine gestrichelte Linie mit der Aktion <code>State-&gt;Counter++</code>: „The type is uint16. After 0xFF'FF, the next value is 0.“.</li>\n<li>Endknoten (Activity Final Node): Ausgefüllter schwarzer Kreis mit äußerer Kreisumrandung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten der Funktion <code>E2E_P04Protect()</code>.</li>\n<li>Die Ausführung führt direkt zur Aktion <code>State-&gt;Counter++</code>, in welcher der Übertragungszähler um eins erhöht wird; erreicht der Wert <code>0xFFFF</code>, erfolgt ein Überlauf zurück auf <code>0</code>.</li>\n<li>Nach Ausführung der Zählerinkrementierung geht der Kontrollfluss unmittelbar in den Endknoten über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß AUTOSAR PRS E2E Protocol für E2E Profile 4:</p>\n<ul class=\"fig-list\">\n<li>Das Zustandselement <code>Counter</code> ist als 16-Bit-Ganzzahl ohne Vorzeichen (<code>uint16</code>) implementiert.</li>\n<li>Der Wertebereich umfasst <code>0x0000</code> bis <code>0xFFFF</code>. Bei Erreichen des Maximalwerts <code>0xFFFF</code> (<code>65535</code>) muss ein arithmetischer Überlauf (Wrap-Around) auf den Wert <code>0</code> erfolgen.</li>\n<li>Der Zählerschritt ist zwingender Bestandteil der Schutzroutine vor bzw. bei der Nachrichtenabsicherung.</li>\n</ul>"}, {"id": "FIG-c0452b2a27317ecf", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des E2E-Profils 4 (E2E Profile 4) innerhalb der AUTOSAR-E2E-Bibliothek (E2E Protocol). Das Diagramm definiert den gemeinsamen Teilschritt „Increment Counter“ innerhalb der Schutzfunktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktionskontexte: <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code> (jeweils dargestellt als abgerundetes Rechteck mit Rake-/Subaktivitätssymbol).</li>\n<li>Startknoten (Initial Node): Ausgefüllter schwarzer Kreis.</li>\n<li>Aktion / Aktivitätszustand: <code>State-&gt;Counter++</code> (Inkrementierung des Zähler-Attributs in der Zustandsstruktur <code>State</code>).</li>\n<li>Notizsymbol (Comment/Note), assoziiert über eine gestrichelte Linie mit der Aktion <code>State-&gt;Counter++</code>: „The type is uint16. After 0xFF'FF, the next value is 0.“.</li>\n<li>Endknoten (Activity Final Node): Ausgefüllter schwarzer Kreis mit äußerer Kreisumrandung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten innerhalb des jeweiligen Funktionskontexts (<code>E2E_P04Protect()</code> bzw. <code>E2E_P04Forward()</code>).</li>\n<li>Die Ausführung führt direkt zur Aktion <code>State-&gt;Counter++</code>, in welcher der Übertragungszähler um eins erhöht wird; erreicht der Wert <code>0xFFFF</code>, erfolgt ein Überlauf zurück auf <code>0</code>.</li>\n<li>Nach Ausführung der Zählerinkrementierung geht der Kontrollfluss unmittelbar in den Endknoten über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß AUTOSAR PRS E2E Protocol für E2E Profile 4:</p>\n<ul class=\"fig-list\">\n<li>Das Zustandselement <code>Counter</code> ist als 16-Bit-Ganzzahl ohne Vorzeichen (<code>uint16</code>) implementiert.</li>\n<li>Der Wertebereich umfasst <code>0x0000</code> bis <code>0xFFFF</code>. Bei Erreichen des Maximalwerts <code>0xFFFF</code> (<code>65535</code>) muss ein arithmetischer Überlauf (Wrap-Around) auf den Wert <code>0</code> erfolgen.</li>\n<li>Das Verhalten des Inkrementierens gilt gleichermaßen für die Schutzfunktion <code>E2E_P04Protect()</code> wie für die Weiterleitungsfunktion <code>E2E_P04Forward()</code>.</li>\n</ul>"}, {"id": "FIG-477b110b3539ac59", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des E2E-Profils 4 (E2E Profile 4) innerhalb der AUTOSAR-E2E-Bibliothek (E2E Protocol). Das Diagramm definiert den gemeinsamen Teilschritt „Increment Counter“ innerhalb der Schutzfunktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktionskontexte: <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code> (jeweils dargestellt als abgerundetes Rechteck mit Rake-/Subaktivitätssymbol).</li>\n<li>Startknoten (Initial Node): Ausgefüllter schwarzer Kreis.</li>\n<li>Aktion / Aktivitätszustand: <code>State-&gt;Counter++</code> (Inkrementierung des Zähler-Attributs in der Zustandsstruktur <code>State</code>).</li>\n<li>Notizsymbol (Comment/Note), assoziiert über eine gestrichelte Linie mit der Aktion <code>State-&gt;Counter++</code>: „The type is uint16. After 0xFF'FF, the next value is 0.“.</li>\n<li>Endknoten (Activity Final Node): Ausgefüllter schwarzer Kreis mit äußerer Kreisumrandung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten innerhalb des jeweiligen Funktionskontexts (<code>E2E_P04Protect()</code> bzw. <code>E2E_P04Forward()</code>).</li>\n<li>Die Ausführung führt direkt zur Aktion <code>State-&gt;Counter++</code>, in welcher der Übertragungszähler um eins erhöht wird; erreicht der Wert <code>0xFFFF</code>, erfolgt ein Überlauf zurück auf <code>0</code>.</li>\n<li>Nach Ausführung der Zählerinkrementierung geht der Kontrollfluss unmittelbar in den Endknoten über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß AUTOSAR PRS E2E Protocol für E2E Profile 4:</p>\n<ul class=\"fig-list\">\n<li>Das Zustandselement <code>Counter</code> ist als 16-Bit-Ganzzahl ohne Vorzeichen (<code>uint16</code>) implementiert.</li>\n<li>Der Wertebereich umfasst <code>0x0000</code> bis <code>0xFFFF</code>. Bei Erreichen des Maximalwerts <code>0xFFFF</code> (<code>65535</code>) muss ein arithmetischer Überlauf (Wrap-Around) auf den Wert <code>0</code> erfolgen.</li>\n<li>Das Verhalten des Inkrementierens gilt gleichermaßen für die Schutzfunktion <code>E2E_P04Protect()</code> wie für die Weiterleitungsfunktion <code>E2E_P04Forward()</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-8f012ddb9fff5ed4", "to": "FIG-c0452b2a27317ecf", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Zusätzlicher Funktionskontext-Knoten <code>E2E_P04Forward()</code> links oben unterhalb von <code>E2E_P04Protect()</code> ergänzt; der Schritt ”Increment Counter” gilt damit normativ auch für die Weiterleitungsfunktion <code>E2E_P04Forward()</code>.</li>\n</ul>"}, {"from": "FIG-c0452b2a27317ecf", "to": "FIG-477b110b3539ac59", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
